/**
 * Bathsheba and Uriah
 * -------------------
 * From his roof David sees Bathsheba bathing; the deed that follows brings Uriah to the front line and judgment on the house. Stage: a royal rooftop at evening, a distant figure at her bath below, a sealed letter passing between hands; purple dusk, a heavy stillness.
 *
 * Palette 0x1a0e08 → 0x0a0604 · light: ember · hero: house
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./david-kit.js.
 */

import { THREE, createScene, column, throne, house, person } from './david-kit.js';

const BG = 0x1a0e08;
const GROUND = 0x040202;

export function build(group) {
    const W = createScene(group, { seed: 1989040371, bg: BG, fogNear: 45, fogFar: 180 });

    /* light — ember */
    W.lights({ sky: 0x3a2418, gnd: 0x1a0e08, hemi: 0.4, sun: 0xff7a30, sunI: 0.7, sunPos: [20, 26, 30] });

    W.stars(90, 150, [0xf0e0c8, 0xd8c0a0], 0.7);
    W.disc([0, 34, -150], 14, 0xff8a30, 0.12);

    /* ground */
    W.ground(260, 260, 0, 0, 0x040202, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* palace: columns, banners and the throne */
    for (let i = -2; i <= 2; i++) column(W, group, i * 8, 0, -30, 11, 1.3, 0x0b0604, { band: 0x140b06 });
    throne(W, group, 0, 0, -24, 1.4, { gold: 0x110905 });

    /* house: mud-brick walls, flat roof, door */
    house(W, group, -14, 0, -17, 1.0 + W.r() * 0.3, { mud: 0x0a0604 });
    house(W, group, -25, 0, -17, 0.8 + W.r() * 0.3, { mud: 0x0a0604 });

    /* hero: the house */
    house(W, group, 0, 0, -2, 1.3, { mud: 0x0a0604 });

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: 0.26, s: 1.02 });

    return W.finish();
}

export default { build };
